dashboard.definition:
{
  "title": "Audit Trail",
  "description": "Aviatrix Controller change tracking: who created, modified or deleted what, when, from where, whether it worked, and which changes matter for security.",
  "inputs": {
    "input_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "time",
        "defaultValue": "-7d@d,now"
      }
    },
    "input_change_filter": {
      "type": "input.dropdown",
      "title": "Operation",
      "options": {
        "token": "change_filter",
        "defaultValue": "NOT change_action=read",
        "items": [
          {
            "label": "Changes (exclude reads)",
            "value": "NOT change_action=read"
          },
          {
            "label": "All operations",
            "value": "change_action=*"
          },
          {
            "label": "Created",
            "value": "change_action=created"
          },
          {
            "label": "Modified",
            "value": "change_action=modified"
          },
          {
            "label": "Deleted",
            "value": "change_action=deleted"
          },
          {
            "label": "Read only",
            "value": "change_action=read"
          }
        ]
      }
    },
    "input_result": {
      "type": "input.dropdown",
      "title": "Result",
      "options": {
        "token": "result",
        "defaultValue": "*",
        "items": [
          {
            "label": "All",
            "value": "*"
          },
          {
            "label": "Success",
            "value": "success"
          },
          {
            "label": "Failure",
            "value": "failure"
          }
        ]
      }
    },
    "input_risk": {
      "type": "input.dropdown",
      "title": "Security relevance",
      "options": {
        "token": "risk",
        "defaultValue": "*",
        "items": [
          {
            "label": "All",
            "value": "*"
          },
          {
            "label": "Security-relevant only",
            "value": "relevant"
          },
          {
            "label": "Logging change",
            "value": "Logging change"
          },
          {
            "label": "Identity change",
            "value": "Identity change"
          },
          {
            "label": "Security policy change",
            "value": "Security policy change"
          }
        ]
      }
    },
    "input_user": {
      "type": "input.text",
      "title": "User",
      "options": {
        "token": "user",
        "defaultValue": "*"
      }
    },
    "input_category": {
      "type": "input.text",
      "title": "Object category",
      "options": {
        "token": "category",
        "defaultValue": "*"
      }
    },
    "input_action_filter": {
      "type": "input.text",
      "title": "Command",
      "options": {
        "token": "action_filter",
        "defaultValue": "*"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$time.earliest$",
            "latest": "$time.latest$"
          }
        }
      }
    }
  },
  "visualizations": {
    "viz_8": {
      "type": "splunk.singlevalue",
      "title": "Operations",
      "dataSources": {
        "primary": "ds_2"
      },
      "options": {
        "majorValue": "> primary | seriesByName(\"total\") | lastPoint()",
        "sparklineValues": "> primary | seriesByName(\"value\")",
        "trendDisplay": "off",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#3987e5",
        "majorColor": "#f0efec",
        "backgroundColor": "#17181b",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 34
      }
    },
    "viz_9": {
      "type": "splunk.singlevalue",
      "title": "Created",
      "dataSources": {
        "primary": "ds_3"
      },
      "options": {
        "majorValue": "> primary | seriesByName(\"total\") | lastPoint()",
        "sparklineValues": "> primary | seriesByName(\"value\")",
        "trendDisplay": "off",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#3987e5",
        "majorColor": "#f0efec",
        "backgroundColor": "#17181b",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 34
      }
    },
    "viz_10": {
      "type": "splunk.singlevalue",
      "title": "Modified",
      "dataSources": {
        "primary": "ds_4"
      },
      "options": {
        "majorValue": "> primary | seriesByName(\"total\") | lastPoint()",
        "sparklineValues": "> primary | seriesByName(\"value\")",
        "trendDisplay": "off",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#3987e5",
        "majorColor": "#f0efec",
        "backgroundColor": "#17181b",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 34
      }
    },
    "viz_11": {
      "type": "splunk.singlevalue",
      "title": "Deleted",
      "dataSources": {
        "primary": "ds_5"
      },
      "options": {
        "majorValue": "> primary | seriesByName(\"total\") | lastPoint()",
        "sparklineValues": "> primary | seriesByName(\"value\")",
        "trendDisplay": "off",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#3987e5",
        "majorColor": "#f0efec",
        "backgroundColor": "#17181b",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 34
      }
    },
    "viz_12": {
      "type": "splunk.singlevalue",
      "title": "Failed",
      "dataSources": {
        "primary": "ds_6"
      },
      "options": {
        "majorValue": "> primary | seriesByName(\"total\") | lastPoint()",
        "sparklineValues": "> primary | seriesByName(\"value\")",
        "trendDisplay": "off",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#d03b3b",
        "majorColor": "> majorValue | rangeValue(alertColors)",
        "backgroundColor": "#17181b",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 34
      },
      "context": {
        "alertColors": [
          {
            "to": 1,
            "value": "#f0efec"
          },
          {
            "from": 1,
            "value": "#d03b3b"
          }
        ]
      }
    },
    "viz_13": {
      "type": "splunk.singlevalue",
      "title": "Security-relevant",
      "dataSources": {
        "primary": "ds_7"
      },
      "options": {
        "majorValue": "> primary | seriesByName(\"total\") | lastPoint()",
        "sparklineValues": "> primary | seriesByName(\"value\")",
        "trendDisplay": "off",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#fab219",
        "majorColor": "> majorValue | rangeValue(alertColors)",
        "backgroundColor": "#17181b",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 34
      },
      "context": {
        "alertColors": [
          {
            "to": 1,
            "value": "#f0efec"
          },
          {
            "from": 1,
            "value": "#fab219"
          }
        ]
      },
      "description": "Logging, identity or policy changes"
    },
    "viz_16": {
      "type": "splunk.column",
      "title": "Operations over time",
      "dataSources": {
        "primary": "ds_14"
      },
      "options": {
        "backgroundColor": "#17181b",
        "legendDisplay": "bottom",
        "xAxisTitleVisibility": "hide",
        "seriesColors": [
          "#3987e5",
          "#d95926",
          "#199e70",
          "#c98500",
          "#d55181",
          "#0ca30c",
          "#9085e9",
          "#e66767"
        ],
        "yAxisTitleVisibility": "hide",
        "seriesColorsByField": {
          "created": "#199e70",
          "modified": "#3987e5",
          "deleted": "#d03b3b",
          "read": "#6b6f76",
          "unknown": "#9085e9"
        },
        "stackMode": "stacked"
      }
    },
    "viz_17": {
      "type": "splunk.punchcard",
      "title": "When changes happen (UTC)",
      "dataSources": {
        "primary": "ds_15"
      },
      "options": {
        "backgroundColor": "#17181b",
        "bubbleColor": "#3987e5",
        "showDefaultSort": false
      },
      "description": "Off-hours activity stands out"
    },
    "viz_section_18": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "#### SECURITY-RELEVANT CHANGES\nLogging changes can be defense evasion; identity changes grant access; policy changes alter enforcement.",
        "fontColor": "#c3c2b7",
        "fontSize": "custom",
        "customFontSize": 13,
        "backgroundColor": "transparent"
      }
    },
    "viz_20": {
      "type": "splunk.table",
      "title": "Security-relevant changes",
      "dataSources": {
        "primary": "ds_19"
      },
      "options": {
        "backgroundColor": "#17181b",
        "count": 9,
        "showInternalFields": false,
        "headerVisibility": "fixed",
        "fontSize": "small",
        "columnFormat": {
          "Operation": {
            "rowColors": "> table | seriesByName(\"Operation\") | matchValue(colors0)"
          },
          "Result": {
            "rowColors": "> table | seriesByName(\"Result\") | matchValue(colors1)"
          },
          "Command": {
            "width": 340
          }
        }
      },
