          "options": {
            "type": "auto",
            "newTab": true
          }
        }
      ]
    }
  },
  "dataSources": {
    "ds_audit_base": {
      "type": "ds.search",
      "name": "ds_audit_base",
      "options": {
        "query": "`aviatrix_audit`\n| `aviatrix_audit_fields`\n| `aviatrix_audit_risk`\n| search username=$user|s$ command=$action_filter|s$ $change_filter$\n| where (\"$result$\"=\"*\" OR result_status=\"$result$\") AND (\"$category$\"=\"*\" OR object_category=\"$category$\") AND (\"$risk$\"=\"*\" OR (\"$risk$\"=\"relevant\" AND isnotnull(audit_risk)) OR audit_risk=\"$risk$\")\n| eval command_group=if(match(command, \"^/\"), replace(replace(command, \"[ ?].*$\", \"\"), \"/([0-9a-fA-F]{8}-[0-9a-fA-F-]{27}|[0-9a-fA-F]{24})(/|$)\", \"/{id}\\2\"), command)\n| fields _time, username, src, controller, change_action, object_category, object, command, command_group, result, result_status, reason, error_code, error_message, audit_risk"
      }
    },
    "ds_2": {
      "type": "ds.chain",
      "name": "ds_2",
      "options": {
        "extend": "ds_audit_base",
        "query": "| timechart count as value\n| fillnull value=0 value\n| eventstats sum(value) as total\n| appendpipe [| stats count as n | where n=0 | eval value=0, total=0 | fields value total]"
      }
    },
    "ds_3": {
      "type": "ds.chain",
      "name": "ds_3",
      "options": {
        "extend": "ds_audit_base",
        "query": "| where change_action=\"created\"\n| timechart count as value\n| fillnull value=0 value\n| eventstats sum(value) as total\n| appendpipe [| stats count as n | where n=0 | eval value=0, total=0 | fields value total]"
      }
    },
    "ds_4": {
      "type": "ds.chain",
      "name": "ds_4",
      "options": {
        "extend": "ds_audit_base",
        "query": "| where change_action=\"modified\"\n| timechart count as value\n| fillnull value=0 value\n| eventstats sum(value) as total\n| appendpipe [| stats count as n | where n=0 | eval value=0, total=0 | fields value total]"
      }
    },
    "ds_5": {
      "type": "ds.chain",
      "name": "ds_5",
      "options": {
        "extend": "ds_audit_base",
        "query": "| where change_action=\"deleted\"\n| timechart count as value\n| fillnull value=0 value\n| eventstats sum(value) as total\n| appendpipe [| stats count as n | where n=0 | eval value=0, total=0 | fields value total]"
      }
    },
    "ds_6": {
      "type": "ds.chain",
      "name": "ds_6",
      "options": {
        "extend": "ds_audit_base",
        "query": "| where result_status=\"failure\"\n| timechart count as value\n| fillnull value=0 value\n| eventstats sum(value) as total\n| appendpipe [| stats count as n | where n=0 | eval value=0, total=0 | fields value total]"
      }
    },
    "ds_7": {
      "type": "ds.chain",
      "name": "ds_7",
      "options": {
        "extend": "ds_audit_base",
        "query": "| where isnotnull(audit_risk)\n| timechart count as value\n| fillnull value=0 value\n| eventstats sum(value) as total\n| appendpipe [| stats count as n | where n=0 | eval value=0, total=0 | fields value total]"
      }
    },
    "ds_14": {
      "type": "ds.chain",
      "name": "ds_14",
      "options": {
        "extend": "ds_audit_base",
        "query": "| timechart count by change_action"
      }
    },
    "ds_15": {
      "type": "ds.chain",
      "name": "ds_15",
      "options": {
        "extend": "ds_audit_base",
        "query": "| eval Hour=strftime(_time, \"%H\"), Day=strftime(_time, \"%w %a\")\n| stats count by Hour Day\n| sort Day Hour"
      }
    },
    "ds_19": {
      "type": "ds.chain",
      "name": "ds_19",
      "options": {
        "extend": "ds_audit_base",
        "query": "| where isnotnull(audit_risk)\n| sort - _time\n| eval Time=strftime(_time, \"%Y-%m-%d %H:%M:%S\"), Details=coalesce(error_message, if(reason==\"None\" OR reason==\"\", null(), substr(reason, 1, 120)), \"-\")\n| rename audit_risk as Category, username as User, src as \"Source IP\", change_action as Operation, command as Command, result_status as Result\n| table Time Category User \"Source IP\" Operation Command Result Details"
      }
    },
    "ds_22": {
      "type": "ds.chain",
      "name": "ds_22",
      "options": {
        "extend": "ds_audit_base",
        "query": "| chart count over username by change_action\n| addtotals fieldname=_total\n| sort - _total | head 10\n| fields - _total"
      }
    },
    "ds_23": {
      "type": "ds.chain",
      "name": "ds_23",
      "options": {
        "extend": "ds_audit_base",
        "query": "| stats count as Count values(change_action) as Operation count(eval(result_status=\"failure\")) as Failed dc(username) as Users latest(_time) as last by command_group\n| eval \"Fail %\"=round(Failed/Count*100, 1), \"Last seen\"=strftime(last, \"%Y-%m-%d %H:%M\")\n| sort - Count\n| rename command_group as Command\n| table Command Operation Count Failed \"Fail %\" Users \"Last seen\""
      }
    },
    "ds_26": {
      "type": "ds.chain",
      "name": "ds_26",
      "options": {
        "extend": "ds_audit_base",
        "query": "| where result_status=\"failure\"\n| eval Error=coalesce(error_code, \"no error code\"), Message=coalesce(error_message, if(reason==\"None\" OR reason==\"\", result, substr(reason, 1, 100)))\n| stats count as Failures dc(username) as Users values(command_group) as cmds latest(_time) as last by Error Message\n| eval Commands=mvjoin(mvindex(cmds, 0, 1), \", \"), \"Last seen\"=strftime(last, \"%Y-%m-%d %H:%M\")\n| sort - Failures\n| table Error Message Failures Users Commands \"Last seen\""
      }
    },
    "ds_27": {
      "type": "ds.chain",
      "name": "ds_27",
      "options": {
        "extend": "ds_audit_base",
        "query": "| stats count by object_category\n| sort - count | head 12"
      }
    },
    "ds_31": {
      "type": "ds.chain",
      "name": "ds_31",
      "options": {
        "extend": "ds_audit_base",
        "query": "| head 500\n| eval Time=strftime(_time, \"%Y-%m-%d %H:%M:%S\")\n| rename username as User, src as \"Source IP\", controller as Controller, change_action as Operation, object_category as Category, command as Command, result as Result, result_status as Status\n| table Time User \"Source IP\" Controller Operation Category Command Result Status"
      }
    }
  },
